const executou = (no) => {
  try {
    return $(no).isExecuted === true;
  } catch (e) {
    return false;
  }
};

// O último "Aplicar" executado vale: reserva 2, reserva 1, principal.
let final;
if (executou('Aplicar resposta da IA (reserva 2)')) final = $('Aplicar resposta da IA (reserva 2)').first().json;
else if (executou('Aplicar resposta da IA (reserva 1)')) final = $('Aplicar resposta da IA (reserva 1)').first().json;
else if (executou('Aplicar resposta da IA')) final = $('Aplicar resposta da IA').first().json;
else if (executou('Aplicar classificador')) final = $('Aplicar classificador').first().json;
else if (executou('Verificar limites da IA')) final = $('Verificar limites da IA').first().json;
else final = $('Resolver conversa').first().json;

// O pedido enviado à IA contém a mensagem do contato: não segue adiante.
const { corpo, pedidos, url, classificador, ...ia } = final.ia ?? {};
return [{ json: { ...final, ia } }];

// Nó "Verificar limites".
// Proteção contra excesso de respostas e laços de mensagens:
//  - total de mensagens atendidas por contato por hora;
//  - mesma resposta repetida para o mesmo contato dentro da janela configurada.

const base = $('Resposta final').first().json;

const primeiroValor = (no) => Number(Object.values($(no).first().json ?? {})[0]) || 0;
const naHora = primeiroValor('Redis: contador por hora');
const iguais = primeiroValor('Redis: contador de respostas iguais');

let responder = true;
let motivo = '';

if (base.silenciar) {
  responder = false;
  motivo = base.motivo || 'fallback_esgotado';
} else if (naHora > base.limites.mensagensPorHora) {
  responder = false;
  motivo = 'limite_de_mensagens_por_hora';
} else if (iguais > base.limites.respostasIguais) {
  responder = false;
  motivo = 'resposta_repetida';
}

return [{ json: { ...base, responder, motivo } }];

// Nó "Dividir em partes". Transforma a resposta final em um item por mensagem a enviar. Resposta pronta
// é uma mensagem só (espera configurada em atraso_resposta_segundos, como sempre). Com várias partes, a
// espera de "digitando" antes de cada uma é proporcional ao tamanho (cerca de 35 ms por caractere,
// entre 1 e 4 segundos).
const base = $('Interpretar mensagem').first().json;
const final = $('Resposta final').first().json;
const partes = (Array.isArray(final.partes) && final.partes.length ? final.partes : [final.resposta])
  .map((parte) => String(parte ?? '')).filter((parte) => parte.trim() !== '');
const lista = partes.length ? partes : [String(final.resposta ?? '')];
return lista.map((texto, indice) => ({ json: {
  texto,
  indice,
  total: lista.length,
  esperaSegundos: lista.length > 1 ? Math.round(Math.min(Math.max(texto.length * 0.035, 1), 4) * 10) / 10 : base.atrasoSegundos,
} }));

// Nó "Consolidar envio". Roda UMA vez, no ramo "done" do laço de envio (todas as partes foram enviadas).
// Prepara a memória da conversa (lista dos últimos turnos, no Redis) e indica se houve bloqueio por
// alguma trava da IA (para o contador de ataques). Mensagens bloqueadas nunca entram na memória.
const base = $('Interpretar mensagem').first().json;
const final = $('Resposta final').first().json;
const ia = final.ia ?? {};
const memoria = final.memoria ?? {};
const partes = (Array.isArray(final.partes) && final.partes.length ? final.partes : [final.resposta])
  .map((parte) => String(parte ?? '')).filter((parte) => parte.trim() !== '');
const textoDoContato = String(base.texto ?? '').trim();

let valorHistorico = '';
const guardarMemoria = memoria.ativa === true && Number(memoria.max) > 0 && !ia.trava && textoDoContato !== '' && partes.length > 0;
if (guardarMemoria) {
  let antigo = [];
  try {
    const bruto = ($('Redis: ler histórico').first().json ?? {}).historico;
    if (bruto) antigo = JSON.parse(String(bruto));
  } catch (e) {
    antigo = [];
  }
  const quando = new Date().toISOString();
  const novos = [
    { de: 'contato', texto: textoDoContato.slice(0, 300), quando },
    { de: 'bot', texto: partes.join('\n').slice(0, 300), quando },
  ];
  const maximo = Math.max(Number(memoria.max) || 0, 0);
  const valido = (item) => item && ['contato', 'bot'].includes(item.de) && typeof item.texto === 'string';
  valorHistorico = JSON.stringify([...(Array.isArray(antigo) ? antigo.filter(valido) : []), ...novos].slice(-maximo));
}

return [{ json: {
  enviadas: partes.length,
  guardarMemoria: guardarMemoria && valorHistorico !== '[]',
  valorHistorico,
  ttlHistorico: 86400,
  bloqueio: ['entrada', 'classificador', 'saida'].includes(ia.trava),
} }];

// Nó "Montar linha de log".
// Uma linha JSON por evento tratado, sem telefone completo e sem o texto da mensagem
// (log de atividade, guardado por LOG_RETENCAO_DIAS). Prepara também a linha da conversa,
// com o texto recebido e a resposta enviada, para a tela "Conversas" do painel; ela é gravada
// pelos nós seguintes em conversas-AAAA-MM-DD.log e apagada após CONVERSAS_RETENCAO_DIAS.

const executou = (no) => {
  try {
    return $(no).isExecuted === true;
  } catch (e) {
    return false;
  }
};
const saida = (no) => {
  try {
    return $(no).first().json ?? {};
  } catch (e) {
    return {};
  }
};

const interpretada = saida('Interpretar mensagem');
const base = executou('Resposta final')
  ? saida('Resposta final')
  : executou('Resolver conversa')
    ? saida('Resolver conversa')
    : interpretada;

let resultado;
let motivo = '';
let detalhe = base.detalhe;
// A saída de erro do envio passa por aqui antes de a falha ser propagada ao registro de erros.
const falhaNoEnvio = executou('Redis: liberar trava (erro no envio)');

if (base.acao === 'ignorar') {
  resultado = 'ignorada';
  motivo = base.motivo;
} else if (base.acao === 'sessao') {
  // Mudança de status do WhatsApp (o momento foi guardado no Redis).
  resultado = 'ignorada';
  motivo = 'status_da_sessao';
} else if (base.acao === 'reativar') {
  resultado = 'robo_reativado';
  motivo = 'comando_do_atendente';
} else if (base.acao === 'pausar') {
  resultado = 'robo_pausado';
  motivo = base.motivo === 'atendente_respondeu' ? 'atendente_respondeu' : 'comando_do_atendente';
} else if (falhaNoEnvio) {
  resultado = 'falha_no_envio';
  motivo = 'erro_no_whatsapp';
} else if (executou('WAHA: enviar resposta')) {
  resultado = 'respondida';
  motivo = base.transferir ? 'transferida_para_atendimento_humano' : base.origem;
} else if (executou('Verificar limites')) {
  resultado = 'silenciada';
  motivo = saida('Verificar limites').motivo;
} else if (executou('Verificar proteções após trava') && saida('Verificar proteções após trava').seguir === false) {
  motivo = saida('Verificar proteções após trava').motivo;
  resultado = motivo === 'recebida_com_o_robo_desligado' ? 'ignorada' : 'silenciada';
} else if (executou('Redis: ler última mensagem')) {
  // Parou na espera: chegou outra mensagem do mesmo contato logo em seguida (só a última é
  // respondida) ou a mensagem era uma pendência de quando o robô estava desligado.
  motivo = saida('Verificar sequência e sessão').motivo || 'agrupada_com_mensagem_seguinte';
  resultado = motivo === 'recebida_com_o_robo_desligado' ? 'ignorada' : 'silenciada';
} else {
  resultado = 'silenciada';
  motivo = saida('Verificar duplicidade e pausa').motivo;
}

if (executou('Redis: sair do atendimento humano')) {
  detalhe = 'contato_voltou_do_atendimento_humano';
}

const quando = $now.toISO();
const ia = (base.ia && base.ia.resultado) || undefined;
// Trava da IA que barrou a mensagem (entrada, classificador, saida ou contato) e nota do classificador.
const trava = (base.ia && base.ia.trava) || undefined;
const iaScore = base.ia && typeof base.ia.score === 'number' ? Math.round(base.ia.score * 100) / 100 : undefined;
// Conversa natural: a IA devia redigir a resposta oficial mas não pôde (falha, limite ou trava): foi a pronta.
const reservaPronta = resultado === 'respondida' && base.ia && base.ia.modo === 'redigir' && base.ia.resultado !== 'respondeu' ? true : undefined;
const partes = resultado === 'respondida' && Array.isArray(base.partes) ? base.partes.length : undefined;
const registro = {
  quando,
  resultado,
  motivo: motivo || undefined,
  evento: base.evento || undefined,
  intencao: base.intencao,
  // Como a IA participou: respondeu, sem_resposta, limite_por_contato, limite_do_dia, erro_429...
  ia,
  // Modelo que respondeu e quantas tentativas falharam antes dele (nunca o texto do contato).
  iaModelo: ia === 'respondeu' && base.ia.modelo ? base.ia.modelo : undefined,
  iaTentativas: Array.isArray(base.ia && base.ia.tentativas) && base.ia.tentativas.length > 0 ? base.ia.tentativas.length : undefined,
  trava,
  iaScore,
  ia_reserva_pronta: reservaPronta,
  partes,
  contato: base.contato,
  msg: base.msg,
  detalhe: detalhe || undefined,
};

// ---------- linha da conversa (com texto) ----------
// Não entram: as respostas do robô que voltam como evento (já registradas junto da mensagem
// que as originou), entregas repetidas da mesma mensagem e eventos sem conversa (status do
// WhatsApp, grupos, canais). Também ficam de fora as mensagens antigas que o WhatsApp entrega
// de uma vez ao reconectar (todas as conversas do celular enquanto o robô esteve desligado):
// não são respondidas e só ocupariam a tela "Conversas" com conversas pessoais.
const NAO_REGISTRAR = ['enviada_pelo_robo', 'mensagem_duplicada', 'mensagem_antiga', 'recebida_com_o_robo_desligado'];
const dados = interpretada.registro;
let conversa = '';
if (dados && typeof dados === 'object' && !NAO_REGISTRAR.includes(motivo)) {
  const doAtendente = ['reativar', 'pausar'].includes(interpretada.acao) || motivo === 'enviada_pelo_atendente';
  let resposta;
  if (resultado === 'respondida' || resultado === 'falha_no_envio') resposta = saida('Resposta final').resposta;
  else if (resultado === 'robo_reativado') resposta = interpretada.resposta;
  conversa = JSON.stringify({
    quando,
    de: doAtendente ? 'atendente' : 'contato',
    sessao: dados.sessao || undefined,
    conversa: dados.conversa,
    telefone: dados.telefone || undefined,
    nome: dados.nome || undefined,
    texto: dados.texto,
    midia: dados.midia || undefined,
    resultado,
    motivo: motivo || undefined,
    intencao: doAtendente ? undefined : base.intencao,
    ia,
    trava,
    ia_reserva_pronta: reservaPronta,
    partes,
    resposta: typeof resposta === 'string' && resposta ? resposta : undefined,
    transferida: base.transferir === true && resultado === 'respondida' ? true : undefined,
    voltou_do_atendimento: detalhe === 'contato_voltou_do_atendimento_humano' ? true : undefined,
    msg: base.msg,
  }) + '\n';
}

return [{ json: { linha: JSON.stringify(registro) + '\n', conversa, falhaNoEnvio } }];

// Nó "Montar linha da conversa".
// Repassa a linha preparada em "Montar linha de log" (texto recebido e resposta enviada).
// Sem conversa a registrar (status do WhatsApp, respostas do próprio robô, entregas
// repetidas), não devolve nada e o ramo termina aqui.
const { conversa, falhaNoEnvio } = $('Montar linha de log').first().json;
if (conversa) return [{ json: { linha: conversa } }];
// A falha de envio ainda precisa chegar ao nó que a propaga ao registro de erros.
if (falhaNoEnvio) throw new Error('CHATBOT_FALHA_ENVIO_WAHA: não foi possível enviar a resposta pelo WhatsApp.');
return [];

// Último nó do atendimento. Quando o envio ao WhatsApp falhou, a saída de erro do HTTP
// passou antes pelo Redis (libera a conversa) e pelos logs; aqui a execução é marcada como
// falha para o workflow "Registro de erros". Propaga só um identificador fixo, sem corpo,
// telefone ou texto recebido.
if ($('Montar linha de log').first().json.falhaNoEnvio === true) {
  throw new Error('CHATBOT_FALHA_ENVIO_WAHA: não foi possível enviar a resposta pelo WhatsApp.');
}
return [];
